From e42e8570cfb6b3ef05795a43473e1a711cf09112 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:11:49 +0100
Subject: [PATCH] shell: don't leave the primary screen without panels on
 unplug

When a screen with panels was disconnected and the primary screen had no
panels of its own, those panels were hidden and nothing was left. Move
them to the primary screen instead, and back once that screen returns.

BUG: 480634
---
 shell/shellcorona.cpp | 27 +++++++++++++++++++++++++++
 1 file changed, 27 insertions(+)

diff --git a/shell/shellcorona.cpp b/shell/shellcorona.cpp
index 51bde18ac6..0c4d73d8e8 100644
--- a/shell/shellcorona.cpp
+++ b/shell/shellcorona.cpp
@@ -278,6 +278,15 @@ void ShellCorona::init()
     connect(this, &ShellCorona::screenRemoved, this, updateManageContainmentsVisiblility);
     updateManageContainmentsVisiblility();

+    connect(this, &ShellCorona::screenAdded, this, [this](int screen) {
+        for (auto *cont : containments()) {
+            if ((cont->containmentType() == Plasma::Containment::Panel || cont->containmentType() == Plasma::Containment::CustomPanel) && cont->screen() == 0
+                && cont->config().readEntry("screenBeforeRemoval", -1) == screen) {
+                setScreenForContainment(cont, screen);
+            }
+        }
+    });
+
     auto *cyclePanelFocusAction = new QAction(this);
     setAction(QStringLiteral("cycle-panels"), cyclePanelFocusAction);
     cyclePanelFocusAction->setText(i18n("Move keyboard focus between panels"));
@@ -1413,6 +1422,23 @@ void ShellCorona::handleScreenRemoved(QScreen *screen)
         // Else do nothing, the view will be recycled
     }

+    const uint removedScreen = m_screenPool->screenOrder().size() - 1;
+    const auto allContainments = containments();
+    const auto isPanel = [](const Plasma::Containment *cont) {
+        return cont->containmentType() == Plasma::Containment::Panel || cont->containmentType() == Plasma::Containment::CustomPanel;
+    };
+    // Don't leave the primary screen without panels: move the removed screen's panels there until that screen comes back
+    if (removedScreen > 0 && std::ranges::none_of(allContainments, [isPanel](const Plasma::Containment *cont) {
+            return isPanel(cont) && cont->screen() == 0;
+        })) {
+        for (auto *cont : allContainments) {
+            if (isPanel(cont) && cont->screen() == removedScreen) {
+                setScreenForContainment(cont, 0);
+                cont->config().writeEntry("screenBeforeRemoval", removedScreen);
+            }
+        }
+    }
+
     // The real screen index that has been removed is *always* the highest one, because we enforce order.
     // There can't be a containment that has for instance screen 0 and another 2 but nothing on 1
     // It's size() - 1 because at this point screenpool didn't remove it from screenOrder() yet
@@ -2660,6 +2686,7 @@ void ShellCorona::setScreenForContainment(Plasma::Containment *containment, uint

     if (containment->containmentType() == Plasma::Containment::Panel || containment->containmentType() == Plasma::Containment::CustomPanel) {
         // Panel Case
+        containment->config().deleteEntry("screenBeforeRemoval");
         auto *panelView = m_panelViews.value(containment);
         // If newScreen != nullptr we are also assured it won't be redundant
         QScreen *newScreen = m_screenPool->screenForId(newScreenId);
